themes.yaml:
config_version: "3.0"
name: Sample Dark
author: Trime Web
description: Gallery fixture：深色配色 × 主鍵盤／符號鍵盤
style:
  keyboard_height: 180
  keyboard_height_land: 140
  key_height: 36
  key_width: 10
  horizontal_gap: 3
  vertical_gap: 5
  round_corner: 8
  candidate_view_height: 28
  candidate_padding: 5
  key_text_size: 18
  key_long_text_size: 14
  symbol_text_size: 10
  enter_labels:
    default: Enter
    done: 完成
    go: 前往
    next: 下個
    pre: 上個
    search: 搜尋
    send: 發送
fallback_colors:
  candidate_text_color: text_color
preset_color_schemes:
  night:
    name: Night
    author: Trime Web
    back_color: 0x1a1d23
    border_color: 0x2a3038
