    hilited_key_text_color: 0xffffff
    hilited_key_back_color: 0x4a90d9
    hilited_key_symbol_color: 0xffffff
    off_key_back_color: 0x3d4450
    off_key_text_color: 0xe8eaed
    on_key_back_color: 0x4a90d9
