    off_key_text_color: 0xf5e6ff
    on_key_back_color: 0xc77dff
    on_key_text_color: 0xffffff
preset_keys:
  Return:
    label: enter_labels
    send: Return
  BackSpace:
    label: ⌫
    send: BackSpace
  Switch_symbols:
    label: 符
    send: Eisu_toggle
    select: symbols
  Go_main:
    label: 返
    send: Eisu_toggle
    select: main
  space:
    label: 空格
    send: space
preset_keyboards:
  main:
    name: 中文
    ascii_mode: 0
    width: 10
    height: 36
    keyboard_height: 180
    keyboard_height_land: 140
    columns: 10
    keys:
      - { click: q, long_click: "1" }
      - { click: w, long_click: "2" }
      - { click: e, long_click: "3" }
      - { click: r, long_click: "4" }
      - { click: t, long_click: "5" }
      - { click: y, long_click: "6" }
      - { click: u, long_click: "7" }
      - { click: i, long_click: "8" }
      - { click: o, long_click: "9" }
      - { click: p, long_click: "0" }
      - { width: 5 }
      - { click: a }
      - { click: s }
      - { click: d }
      - { click: f }
      - { click: g }
      - { click: h }
      - { click: j }
      - { click: k }
      - { click: l }
      - { width: 5 }
      - { click: Switch_symbols, width: 15, label: 符 }
      - { click: z }
      - { click: x }
      - { click: c }
      - { click: v }
      - { click: b }
      - { click: n }
      - { click: m }
      - { click: BackSpace, width: 15, label: ⌫ }
      - { click: Switch_symbols, width: 15, label: 符 }
      - { click: ",", width: 10 }
      - { click: space, width: 50, label: 空格 }
      - { click: ".", width: 10 }
      - { click: Return, width: 15 }
  symbols:
    name: 符號
    ascii_mode: 1
    reset_ascii_mode: true
    width: 10
    height: 36
    keyboard_height: 180
    keyboard_height_land: 140
    columns: 10
    keys:
      - { click: "1" }
      - { click: "2" }
      - { click: "3" }
      - { click: "4" }
      - { click: "5" }
      - { click: "6" }
      - { click: "7" }
      - { click: "8" }
      - { click: "9" }
      - { click: "0" }
      - { click: "@" }
      - { click: "#" }
      - { click: "$" }
      - { click: "%" }
      - { click: "&" }
      - { click: "*" }
      - { click: "-" }
      - { click: "+" }
      - { click: "(" }
      - { click: ")" }
      - { click: "!" }
      - { click: '"' }
      - { click: "'" }
      - { click: ":" }
      - { click: ";" }
      - { click: "/" }
      - { click: "?" }
      - { click: "~" }
      - { click: BackSpace, width: 20, label: ⌫ }
      - { click: Go_main, width: 20, label: 返 }
      - { click: space, width: 45, label: 空格 }
      - { click: Return, width: 15 }
